class Solution { public:
 int nonSpecialCount(int l,int r) {
  int m=sqrt((double)r);vector<bool> prime(m+1,true);if(m>=0)prime[0]=false;if(m>=1)prime[1]=false;
  for(int p=2;p*p<=m;++p)if(prime[p])for(int j=p*p;j<=m;j+=p)prime[j]=false;
  int special=0;for(int p=2;p<=m;++p)if(prime[p] && 1LL*p*p>=l)++special;
  return r-l+1-special;
 }
};
